import { defineSlot } from '../Slot';

/**
 * The people table. A feature that shows something per person adds a column (a heading in
 * PersonColumnHead and a <td> in PersonCells) or rows under the person's own row (PersonDetail,
 * each contribution rendering its own <tr>, spanning PERSON_ROW_SPAN columns). All of it sits
 * inside the person's `person-row-<id>` element.
 */
export const PersonColumnHead = defineSlot<{ sheetId: string }>('person.columnHead');
export const PersonCells = defineSlot<{ sheetId: string; personId: number }>('person.cells');
export const PersonDetail = defineSlot<{ sheetId: string; personId: number }>('person.detail');

/** colSpan for a PersonDetail row: wide enough for every column. */
export const PERSON_ROW_SPAN = 100;
import { Fragment, createElement } from 'react';
import type { ComponentType, ReactElement } from 'react';
import { forSlot } from './registry';

// ── Slots: regions of the UI that features fill ───────────────────────────────────────────────
// A SLOT is a region of the UI that features fill. Whatever renders a region does not list what
// goes in it; a contribution to a region (a panel, a table column, a row action, a toolbar
// control, a nav link) is a separate file, registered by discovery (slots/discover.ts).
//
//   1. declare a region  ->  slots/defs/projectDetail.ts
//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
//   3. fill it           ->  features/projects/notes.slot.tsx
//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
//
// This file, slots/registry.ts and slots/discover.ts implement that mechanism; a region is
// declared by a file under slots/defs/.

export type Contribution<Ctx> = {
  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
  order?: number;
  Component: ComponentType<Ctx>;
};

export type SlotDef<Ctx extends object> = {
  id: string;
  /** Renders the region. Its props ARE the context handed to every contribution. */
  Slot: (ctx: Ctx) => ReactElement;
  /** A feature wraps its contribution in this, to be typed against the region's context. */
  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
};

export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
  return {
    id,
    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
    // row actions are slots too), where a stray <div> would be invalid markup.
    Slot: (ctx: Ctx) =>
      createElement(
        Fragment,
        null,
        forSlot(id).map((c) =>
          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
        ),
      ),
    fill: (contribution) => ({ slot: id, ...contribution }),
  };
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { SheetBody } from '../../slots/defs/sheetBody';
import { LOCALES, localeKey, useLocale, type UserLocale } from './useLocale';

/** The signed-in user's locale, shown and changeable: how the screen shows them figures (useFigure). It is kept
 *  for the user, whatever sheet is loaded, and writes no audit line. */
function LocaleControl({ user }: { user: string }) {
  const locale = useLocale();
  const [chosen, setChosen] = useState<string | null>(null);
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (raw: string) => postJson<UserLocale>('/api/locale', { locale: raw }),
    onSuccess: (saved) => {
      queryClient.setQueryData(localeKey(user), saved);
      setChosen(null);
    },
  });

  return (
    <form
      data-testid="user-locale-form"
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          save.reset();
          return save.mutateAsync(chosen ?? locale);
        });
      }}
    >
      Locale: <strong data-testid="user-locale-current">{locale}</strong>{' '}
      <select
        data-testid="user-locale"
        value={chosen ?? locale}
        onChange={(e) => {
          setChosen(e.target.value);
          save.reset();
        }}
      >
        {LOCALES.map((l) => (
          <option key={l} value={l}>
            {l}
          </option>
        ))}
      </select>{' '}
      <button type="submit" data-testid="user-locale-save" disabled={save.isPending}>
        Save locale
      </button>
      {save.isError && <p data-testid="user-locale-error">{save.error.message}</p>}
    </form>
  );
}

export const contribution = SheetBody.fill({ order: -20, Component: ({ user }) => <LocaleControl user={user} /> });
import { useQuery } from '@tanstack/react-query';
import { getJsonNow } from '../../api/http';
import { useSignedInUser } from '../session/useSession';

export const LOCALES = ['en', 'de'] as const;
export type UserLocale = { locale: string };

/** The signed-in user's locale is theirs, not a sheet's: kept under its own key, not dropped when a sheet loads. */
export const localeKey = (user: string) => ['user', user, 'locale'];

/** The signed-in user's locale ('en' until they choose, and while it is being read). */
export function useLocale(): string {
  const [user] = useSignedInUser();
  const locale = useQuery({
    queryKey: localeKey(user),
    queryFn: () => getJsonNow<UserLocale>('/api/locale'),
    enabled: user !== '',
  });
  return locale.data?.locale ?? 'en';
}

/** A figure: the whole text a number with two decimals. */
const FIGURE = /^(-?)(\d+)\.(\d{2})$/;

/** A shown value as this locale shows it: under 'de' a figure reads 1.234,56 (a dot every three digits, a comma
 *  before the decimals); anything else, and every value under 'en', is shown as it is. Only what the screen shows
 *  goes through this: entries are typed with a dot, and exports and audit lines keep the dot. */
export function figureIn(locale: string, value: string): string {
  const m = locale === 'de' ? FIGURE.exec(value.trim()) : null;
  if (!m) return value;
  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+$)/g, '.')},${m[3]}`;
}

/** Shows a value as the signed-in user's locale does (figureIn); a value that is not text is shown as it is. */
export function useFigure(): <T>(value: T) => T | string {
  const locale = useLocale();
  return <T,>(value: T) => (typeof value === 'string' ? figureIn(locale, value) : value);
}
