import { asString, useSearchParam } from '../../url/useSearchParam';
import { setSignedInUser } from '../../api/http';

/** The signed-in name (URL key `user`); '' when no one is signed in. */
export function useSignedInUser(): [string, (name: string | undefined) => void] {
  const [user, setUser] = useSearchParam('user', asString);
  setSignedInUser(user);
  return [user, setUser];
}

/** The id of the active sheet (URL key `sheet`); '' when none is loaded. */
export function useActiveSheet(): [string, (id: string | undefined) => void] {
  return useSearchParam('sheet', asString);
}
import { defineSlot } from '../Slot';

/**
 * The body of the active sheet, rendered once a user is signed in and a sheet is loaded. A
 * feature that shows or changes a sheet's data fills this region. Its data lives under query
 * keys starting ['sheet', sheetId, ...]: loading a sheet drops every such key, so the whole
 * sheet is re-read from the store.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');

